package com.mathengine.app;
import android.app.*;import android.os.Bundle;import android.view.View;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.Gravity;import android.widget.*;import android.text.InputType;
import com.mathengine.engine.CalculatorEngine;import com.mathengine.storage.HistoryStore;import com.mathengine.units.UnitConverter;import com.mathengine.finance.*;import com.mathengine.data.OfflineCurrencyRates;
public final class MainActivity extends Activity{
private final int BG=0xff10110f,KEY=0xff2b2e28,PANEL=0xff1e201c,ACCENT=0xffd7ff64,MUTED=0xff9ea494;private CalculatorEngine engine=new CalculatorEngine();private HistoryStore history;private TextView expression,result,mode;private String current="";private boolean evaluated=false,degrees=true;
@Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);history=new HistoryStore(this);build();}
private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);t.setIncludeFontPadding(false);return t;}
private GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(24));return d;}
private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(16),dp(18),dp(12));root.setBackgroundColor(BG);setContentView(root);
LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);mode=text("DEG",14,ACCENT);mode.setGravity(Gravity.CENTER);mode.setOnClickListener(v->{degrees=!degrees;engine.setDegrees(degrees);mode.setText(degrees?"DEG":"RAD");});top.addView(mode,new LinearLayout.LayoutParams(dp(58),dp(44)));View spacer=new View(this);top.addView(spacer,new LinearLayout.LayoutParams(0,1,1));Button hist=small("↺"),tools=small("⋯");hist.setOnClickListener(v->showHistory());tools.setOnClickListener(v->showTools());top.addView(hist);top.addView(tools);root.addView(top);
LinearLayout display=new LinearLayout(this);display.setOrientation(1);display.setGravity(Gravity.BOTTOM|Gravity.END);display.setPadding(0,dp(20),0,dp(20));root.addView(display,new LinearLayout.LayoutParams(-1,0,1));expression=text("",24,MUTED);expression.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);display.addView(expression,new LinearLayout.LayoutParams(-1,dp(52)));result=text("0",50,Color.WHITE);result.setTypeface(Typeface.create("sans-serif-light",0));result.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);display.addView(result,new LinearLayout.LayoutParams(-1,dp(76)));
String[][] rows={{"sin","cos","tan","√"},{"ln","log","x²","π"},{"AC","( )","%","÷"},{"7","8","9","×"},{"4","5","6","−"},{"1","2","3","+"},{"⌫","0",".","="}};GridLayout grid=new GridLayout(this);grid.setColumnCount(4);grid.setRowCount(rows.length);root.addView(grid,new LinearLayout.LayoutParams(-1,0,3.3f));
for(int r=0;r<rows.length;r++)for(int c=0;c<4;c++){String k=rows[r][c];Button b=new Button(this);b.setText(k);b.setAllCaps(false);b.setTextSize(k.equals("=")?25:20);b.setTextColor(k.equals("=")?BG:(c==3?ACCENT:Color.WHITE));b.setBackground(shape(k.equals("=")?ACCENT:(k.equals("AC")||k.equals("( )")||k.equals("%")?PANEL:KEY)));GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.height=0;p.columnSpec=GridLayout.spec(c,1,1f);p.rowSpec=GridLayout.spec(r,1,1f);p.setMargins(dp(4),dp(4),dp(4),dp(4));grid.addView(b,p);b.setOnClickListener(v->tap(k));}}
private Button small(String s){Button b=new Button(this);b.setText(s);b.setTextSize(22);b.setTextColor(Color.WHITE);b.setBackground(shape(KEY));b.setMinWidth(dp(48));return b;}
private void tap(String k){try{if(k.equals("AC")){current="";evaluated=false;expression.setText("");result.setText("0");return;}if(k.equals("⌫")){if(!current.isEmpty())current=current.substring(0,current.length()-1);expression.setText(current);result.setText(current.isEmpty()?"0":current);evaluated=false;return;}if(k.equals("=")){if(current.isEmpty())return;String ans=engine.evaluate(current);history.add(current,ans);expression.setText(current);result.setText(ans);current=ans;evaluated=true;return;}if(k.equals("sin")||k.equals("cos")||k.equals("tan")||k.equals("ln")||k.equals("log"))k+="(";if(k.equals("√"))k="sqrt(";if(k.equals("x²"))k="^2";if(k.equals("( )")){long a=current.chars().filter(x->x=='(').count(),b=current.chars().filter(x->x==')').count();k=a>b?")":"(";}if(evaluated&&(Character.isDigit(k.charAt(0))||k.equals(".")))current="";evaluated=false;current+=k;expression.setText(current);result.setText(current);}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_SHORT).show();}}
private void showHistory(){java.util.List<String> rows=history.all();if(rows.isEmpty()){Toast.makeText(this,"No history",0).show();return;}StringBuilder s=new StringBuilder();for(String x:rows)s.append(x.replace('\t',' ')).append('\n');new AlertDialog.Builder(this).setTitle("History").setMessage(s.toString()).setNegativeButton("Close",null).setNeutralButton("Clear",(d,w)->history.clear()).show();}
private void showTools(){String[] a={"BMI","Discount","GST","Mortgage","Simple interest","Compound interest","Number base","Date difference","Unit converter","Offline currency"};new AlertDialog.Builder(this).setTitle("Tools").setItems(a,(d,i)->{switch(i){case 0:prompt("BMI",new String[]{"Weight kg","Height cm"},v->show("BMI",String.format("%.1f",QuickTools.bmi(v[0],v[1]))));break;case 1:prompt("Discount",new String[]{"Original price","Discount %"},v->show("Final price",fmt(QuickTools.discountPrice(v[0],v[1]))));break;case 2:prompt("GST",new String[]{"Base amount","Tax %"},v->{double t=QuickTools.gstAmount(v[0],v[1]);show("GST / total",fmt(t)+" / "+fmt(v[0]+t));});break;case 3:prompt("Mortgage",new String[]{"Principal","Annual rate %","Months"},v->{MortgageCalculator.Result x=new MortgageCalculator().calculate(v[0],v[1],(int)v[2]);show("Monthly payment",fmt(x.monthlyPayment)+"\nInterest: "+fmt(x.totalInterest));});break;case 4:prompt("Simple interest",new String[]{"Principal","Annual rate %","Years"},v->{double x=new InterestCalculator().simpleInterest(v[0],v[1],v[2]);show("Interest / total",fmt(x)+" / "+fmt(x+v[0]));});break;case 5:prompt("Compound interest",new String[]{"Principal","Annual rate %","Compounds/year","Years"},v->{double x=new InterestCalculator().compoundAmount(v[0],v[1],(int)v[2],v[3]);show("Interest / total",fmt(x-v[0])+" / "+fmt(x));});break;case 6:radix();break;case 7:dates();break;case 8:units();break;case 9:currency();break;}}).show();}
private interface Action{void run(double[] v);}private void prompt(String title,String[] labels,Action a){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(8),dp(18),dp(4));EditText[] e=new EditText[labels.length];for(int i=0;i<e.length;i++){e[i]=new EditText(this);e[i].setSingleLine(true);e[i].setHint(labels[i]);e[i].setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);box.addView(e[i]);}new AlertDialog.Builder(this).setTitle(title).setView(box).setNegativeButton("Cancel",null).setPositiveButton("Calculate",(d,w)->{try{double[] v=new double[e.length];for(int i=0;i<e.length;i++)v[i]=Double.parseDouble(e[i].getText().toString());a.run(v);}catch(Exception x){show("Input error",x.getMessage());}}).show();}
private void radix(){LinearLayout b=form(new String[]{"Number","From base","To base"});EditText[] e=fields(b);new AlertDialog.Builder(this).setTitle("Number base converter").setView(b).setNegativeButton("Cancel",null).setPositiveButton("Convert",(d,w)->{try{show("Result",QuickTools.convertRadix(e[0].getText().toString(),Integer.parseInt(e[1].getText().toString()),Integer.parseInt(e[2].getText().toString())));}catch(Exception x){show("Error",x.getMessage());}}).show();}
private void dates(){LinearLayout b=form(new String[]{"Start YYYY-MM-DD","End YYYY-MM-DD"});EditText[] e=fields(b);for(EditText x:e)x.setInputType(InputType.TYPE_CLASS_DATETIME);new AlertDialog.Builder(this).setTitle("Date difference").setView(b).setNegativeButton("Cancel",null).setPositiveButton("Calculate",(d,w)->{try{show("Days",Long.toString(QuickTools.daysBetween(e[0].getText().toString(),e[1].getText().toString())));}catch(Exception x){show("Error",x.getMessage());}}).show();}
private LinearLayout form(String[] labels){LinearLayout b=new LinearLayout(this);b.setOrientation(1);b.setPadding(dp(18),dp(8),dp(18),dp(4));for(String s:labels){EditText e=new EditText(this);e.setHint(s);b.addView(e);}return b;}
private EditText[] fields(LinearLayout b){EditText[] e=new EditText[b.getChildCount()];for(int i=0;i<e.length;i++)e[i]=(EditText)b.getChildAt(i);return e;}
private void units(){String[] cats={"Length","Mass","Time","Area","Volume","Data","Speed","Temperature"};new AlertDialog.Builder(this).setTitle("Unit converter").setItems(cats,(d,i)->{UnitConverter u=new UnitConverter();UnitConverter.Category c=UnitConverter.Category.values()[i];String[] names=u.units(c);new AlertDialog.Builder(this).setTitle("From unit").setItems(names,(d2,f)->new AlertDialog.Builder(this).setTitle("To unit").setItems(names,(d3,t)->prompt("Value in "+names[f],new String[]{"Value"},v->show("Converted",u.format(u.convert(v[0],c,f,t))+" "+names[t]))).show()).show();}).show();}
private void currency(){LinearLayout b=form(new String[]{"Amount","From currency (e.g. USD)","To currency (e.g. BDT)"});EditText[] e=fields(b);e[1].setInputType(InputType.TYPE_CLASS_TEXT);e[2].setInputType(InputType.TYPE_CLASS_TEXT);new AlertDialog.Builder(this).setTitle("Offline currency").setMessage("Bundled offline rate snapshot").setView(b).setNegativeButton("Cancel",null).setPositiveButton("Convert",(d,w)->{try{double v=Double.parseDouble(e[0].getText().toString());double x=new OfflineCurrencyRates(this).convert(v,e[1].getText().toString(),e[2].getText().toString());show("Result",fmt(x)+" "+e[2].getText());}catch(Exception x){show("Unavailable",x.getMessage());}}).show();}
private void show(String t,String s){new AlertDialog.Builder(this).setTitle(t).setMessage(s).setPositiveButton("OK",null).show();}private String fmt(double x){return new java.text.DecimalFormat("#,##0.####").format(x);}
}
